import{fetchCohortJSON}from'./current-cohort-loader.js';import{freshState}from'./model.js';import{saveExplorerAnswer}from'./explorer-053-state.js';import{explorerResults}from'./open-explorer-090.js';import{researchOffer104 as boardOffer}from'./research-offer-104.js';import{explorerBudget}from'./explorer-053-budget.js';import{onetQuestions,onetResponseOptions}from'./onet-assessment.js';
const $=id=>document.getElementById(id),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),frame=$('results-board-frame'),p=new URL(location.href).searchParams;let catalog,journeys,record,j,arm=p.get('arm')==='targeted'?'targeted':'previous',data,step='results';
const send=()=>{if(data)frame.contentWindow.postMessage({type:'fieldguide-board-init',data,preview:true},location.origin);};const viewport=()=>frame.contentWindow.postMessage({type:'fieldguide-board-viewport',top:Math.max(0,-frame.getBoundingClientRect().top)+16,height:Math.max(250,window.innerHeight-48)},location.origin);
window.addEventListener('scroll',viewport,{passive:true});window.addEventListener('resize',viewport);window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==frame.contentWindow)return;const m=e.data;if(m?.type==='fieldguide-board-ready'){send();viewport();}if(m?.type==='fieldguide-board-height'&&Number.isFinite(m.height))frame.style.height=Math.max(800,Math.min(50000,m.height))+'px';if(m?.type==='fieldguide-board-dialog')viewport();if(m?.type==='fieldguide-board-save'&&data)data.saved=m.saved?[...new Set([...data.saved,m.id])]:data.saved.filter(id=>id!==m.id);if(m?.type==='fieldguide-board-navigate')$('status').textContent=record.name+' · Read-only model preview. Your own plan is unchanged.';});frame.addEventListener('load',send);
function show(){for(const b of $('steps').querySelectorAll('button'))b.setAttribute('aria-pressed',String(b.dataset.step===step));$('trace').hidden=step==='results';frame.hidden=step!=='results';if(step==='results'){send();return;}const goal=record.lifestyle;if(step==='lifestyle'){$('trace').innerHTML='<h1>Selected lifestyle</h1><p><b>$'+Math.round(goal.target).toLocaleString()+' / year needed</b></p><p>$'+Math.round(goal.monthlySpending).toLocaleString()+' monthly spending · $'+Math.round(goal.comfortable).toLocaleString()+' annual breathing-room target</p><p>These are this model’s frozen lifestyle assumptions.</p>';return;}if(step==='interest'){$('trace').innerHTML='<h1>60 profiler answers</h1><ol>'+onetQuestions.map(q=>'<li><b>'+h(q.text)+'</b><br>'+h(onetResponseOptions.find(a=>a.value===Number(j.officialInterest.answers[q.id]))?.label||'Unknown')+'</li>').join('')+'</ol><p>Includes the O*NET® Interest Profiler Short Form by the U.S. Department of Labor, Employment and Training Administration (USDOL/ETA). Used under <a href="https://creativecommons.org/licenses/by-nd/4.0/">CC BY-ND 4.0</a>. O*NET® is a trademark of USDOL/ETA.</p>';return;}$('trace').innerHTML='<h1>'+j.arms[arm].length+' adaptive follow-up answers</h1><p>Each next question used only answers already observed. Unknown answers count toward the24-item limit.</p><ol>'+j.arms[arm].map(([,qid,ai])=>{const q=journeys.questions[qid],a=journeys.payloads[ai];return'<li><b>'+h(q.prompt)+'</b><br>'+h(a.response==='unfamiliar'?'Unknown':a.response)+(a.selected?.length?'<br>'+q.options.filter(o=>a.selected.includes(o.id)).map(o=>h(o.text)).join('; '):'')+'</li>';}).join('')+'</ol>';}
function choose(id){record=catalog.rows.find(r=>r.id===id);j=journeys.rows.find(r=>r.id===id);if(!record||!j)throw Error('Choose a model from the fresh matrix.');const s=freshState();s.profile.nickname=record.name;s.finance=structuredClone(j.finance);s.guide.lifestyleBuilder=structuredClone(j.lifestyleBuilder);s.profileJourney={officialInterest:structuredClone(j.officialInterest)};for(const[cid,qid,ai]of j.arms[arm]){const q=journeys.questions[qid],task=q.options&&!['specific','core-work'].includes(q.kind);saveExplorerAnswer(s,{kind:task?'field':'profession',scope:task?q.field:cid,questionId:qid,payload:journeys.payloads[ai],at:'2026-10-24T00:00:00.000Z'});}
 const rows=explorerResults(s).rows,sup=rows.filter(r=>r.specific.supported),candidates=rows.filter(r=>!r.specific.supported&&(r.r>=.608||r.specific.evidence.length||r.activityTopics?.length)),expected=record.arms[arm].offers.filter(o=>o[2]===2).map(o=>o[0]);if(JSON.stringify(sup.slice(0,3).map(r=>r.id))!==JSON.stringify(expected)||JSON.stringify(sup.map(r=>r.id))!==JSON.stringify(record.arms[arm].offers.filter(o=>o[2]>0).map(o=>o[0])))throw Error('Journey and matrix versions disagree. Reload before using these results.');const pack=(r,i,candidate)=>boardOffer(r.o,{rank:i,top:!candidate&&i<3,candidate,fields:r.fields,amount:explorerBudget(s,r.o).amount,r:r.r,mixed:!!r.specific.contrary.length,evidence:r.specific.evidence.map(e=>e.text).slice(0,3),confirmation:{requirement:r.specific.requirement,asked:r.specific.asked,taskContexts:r.specific.taskDomains.length,specificInterests:r.specific.specificDomains.length,missing:r.specific.missing.map(q=>q.prompt),contrary:r.specific.contrary.map(q=>q.prompt)}});
 data={fields:catalog.fields,saved:[],profiles:[{...record,firstName:record.name.split(' ')[0],profileAnswered:60,profileComplete:true,lifestyle:record.lifestyle,supported:sup.map((r,i)=>pack(r,i,false)),candidates:candidates.map((r,i)=>pack(r,i,true)),candidateCount:candidates.length}]};$('status').textContent=record.name+' · '+record.cohort+' · '+(arm==='previous'?'Current research control':'Replacement experiment · not adopted')+' · Fresh 60 + '+j.arms[arm].length+' · Your own plan is unchanged.';$('back').href='/developer/student-matrix-104.html?arm='+(arm==='previous'?'control':'targeted');const u=new URL(location.href);u.searchParams.set('model',id);u.searchParams.set('arm',arm==='previous'?'control':'targeted');history.replaceState({},'',u);$('model').value=id;show();}
$('steps').onclick=e=>{const b=e.target.closest('button[data-step]');if(b){step=b.dataset.step;show();}};$('model').onchange=()=>choose($('model').value);$('arm').onchange=()=>{arm=$('arm').value;choose(record.id);};
try{[catalog,journeys]=await Promise.all([fetchCohortJSON('/developer/matrix-104.json.gz'),fetchCohortJSON('/developer/journeys-104.json.gz')]);$('model').innerHTML=catalog.rows.map(r=>'<option value="'+h(r.id)+'">'+h(r.name)+' · '+h(r.id)+'</option>').join('');$('arm').value=arm;choose(p.get('model')||catalog.rows[0].id);}catch(e){$('status').textContent='Could not open the exact fresh results: '+e.message;frame.hidden=true;}
